{
    if (_isContinuousRunning)
    {
        // 停止连续运行
        _isContinuousRunning = false;
        ContinuousRunButton.Content = "连续执行";
        RunButton.Visibility = Visibility.Visible;
    }
    else
    {
        // 开始连续运行
